PRAGMA foreign_keys = ON;
BEGIN;
CREATE TABLE skjemaversjon (versjon INTEGER PRIMARY KEY, beskrivelse TEXT NOT NULL);
INSERT INTO skjemaversjon VALUES (1,'Felles analysegrunnlag for Steigen');
CREATE TABLE datakilde (id INTEGER PRIMARY KEY, navn TEXT NOT NULL UNIQUE, opprinnelse TEXT NOT NULL, oppdatert TEXT NOT NULL, sha256 TEXT NOT NULL CHECK(length(sha256)=64));
CREATE TABLE datasett (navn TEXT PRIMARY KEY, metadata TEXT NOT NULL CHECK(json_valid(metadata)), datakilde_id INTEGER NOT NULL REFERENCES datakilde(id));
CREATE TABLE sektor (id INTEGER PRIMARY KEY CHECK(id>=0), navn TEXT NOT NULL, egenskaper TEXT NOT NULL CHECK(json_valid(egenskaper)));
CREATE TABLE tjenesteomraade (id INTEGER PRIMARY KEY CHECK(id>=0), navn TEXT NOT NULL, sektor_id INTEGER NOT NULL REFERENCES sektor(id), egenskaper TEXT NOT NULL CHECK(json_valid(egenskaper)));
CREATE TABLE artsgruppe (id INTEGER PRIMARY KEY, navn TEXT NOT NULL, egenskaper TEXT NOT NULL CHECK(json_valid(egenskaper)));
CREATE TABLE varegruppe (id INTEGER PRIMARY KEY, navn TEXT NOT NULL);
CREATE TABLE mottakergruppe (id INTEGER PRIMARY KEY, navn TEXT NOT NULL);
CREATE TABLE bransje (id INTEGER PRIMARY KEY, navn TEXT NOT NULL);
CREATE TABLE leverandoer (id INTEGER PRIMARY KEY, navn TEXT NOT NULL, bransje_id INTEGER NOT NULL REFERENCES bransje(id));
CREATE TABLE konto (id INTEGER PRIMARY KEY, nummer INTEGER NOT NULL UNIQUE, navn TEXT NOT NULL, art INTEGER NOT NULL, investering INTEGER NOT NULL CHECK(investering IN(0,1)), artsgruppe_id INTEGER NOT NULL REFERENCES artsgruppe(id), varegruppe_id INTEGER NOT NULL REFERENCES varegruppe(id));
CREATE TABLE funksjon (id INTEGER PRIMARY KEY, nummer INTEGER NOT NULL UNIQUE, navn TEXT NOT NULL, tjenesteomraade_id INTEGER NOT NULL REFERENCES tjenesteomraade(id), mottakergruppe_id INTEGER NOT NULL REFERENCES mottakergruppe(id));
CREATE TABLE transaksjon (id INTEGER PRIMARY KEY, periode INTEGER NOT NULL CHECK(periode BETWEEN 190001 AND 220012 AND periode%100 BETWEEN 0 AND 12), konto_id INTEGER NOT NULL REFERENCES konto(id), funksjon_id INTEGER NOT NULL REFERENCES funksjon(id), leverandoer_id INTEGER NOT NULL REFERENCES leverandoer(id), belop_oere INTEGER NOT NULL, serie INTEGER NOT NULL, bilag INTEGER NOT NULL, datakilde_id INTEGER NOT NULL REFERENCES datakilde(id));
CREATE INDEX transaksjon_periode ON transaksjon(periode);
CREATE INDEX transaksjon_leverandoer ON transaksjon(leverandoer_id,periode);
CREATE INDEX transaksjon_funksjon ON transaksjon(funksjon_id,periode);
CREATE TABLE grunnkrets (nummer TEXT PRIMARY KEY, navn TEXT NOT NULL, lengdegrad REAL, breddegrad REAL, geometri TEXT CHECK(geometri IS NULL OR json_valid(geometri)));
CREATE TABLE eiendomsskatt (aar INTEGER NOT NULL CHECK(aar BETWEEN 1900 AND 2200), grunnkrets_nr TEXT NOT NULL REFERENCES grunnkrets(nummer), fritakklasse INTEGER NOT NULL CHECK(fritakklasse IN(0,1,2)), skatt_oere INTEGER NOT NULL, antall INTEGER NOT NULL CHECK(antall>=0), takst_oere INTEGER NOT NULL, grunnlag_oere INTEGER NOT NULL, areal_m2 REAL NOT NULL CHECK(areal_m2>=0), antall_med_areal INTEGER NOT NULL CHECK(antall_med_areal BETWEEN 0 AND antall), skatt_med_areal_oere INTEGER NOT NULL, datakilde_id INTEGER NOT NULL REFERENCES datakilde(id), PRIMARY KEY(aar,grunnkrets_nr,fritakklasse));
CREATE INDEX eiendomsskatt_grunnkrets ON eiendomsskatt(grunnkrets_nr,aar);
CREATE TABLE byggkategori (gruppe TEXT NOT NULL CHECK(gruppe IN('bygningstype','bygningsstatus')), id TEXT NOT NULL, navn TEXT NOT NULL, sortering INTEGER NOT NULL, PRIMARY KEY(gruppe,id));
CREATE TABLE byggantall (gruppe TEXT NOT NULL, kategori_id TEXT NOT NULL, grunnkrets_nr TEXT NOT NULL REFERENCES grunnkrets(nummer), antall INTEGER NOT NULL CHECK(antall>=0), datakilde_id INTEGER NOT NULL REFERENCES datakilde(id), PRIMARY KEY(gruppe,kategori_id,grunnkrets_nr), FOREIGN KEY(gruppe,kategori_id) REFERENCES byggkategori(gruppe,id));
CREATE TABLE statistikkserie (datasett TEXT NOT NULL, sti TEXT NOT NULL CHECK(json_valid(sti)), aar INTEGER NOT NULL, verdi REAL, datakilde_id INTEGER NOT NULL REFERENCES datakilde(id), PRIMARY KEY(datasett,sti,aar));
CREATE TABLE beregningsregel (id INTEGER PRIMARY KEY CHECK(id=1), parametere TEXT NOT NULL CHECK(json_valid(parametere)), verifisert INTEGER NOT NULL DEFAULT 0 CHECK(verifisert IN(0,1)), merknad TEXT NOT NULL);
CREATE VIEW v_utgifter_per_aar AS SELECT CAST(periode/100 AS INTEGER) AS aar, COUNT(*) AS antall_linjer, SUM(belop_oere)/100.0 AS sum_belop_kr FROM transaksjon GROUP BY CAST(periode/100 AS INTEGER);
CREATE VIEW v_utgifter_per_leverandoer AS SELECT l.id,l.navn,CAST(t.periode/100 AS INTEGER) AS aar,COUNT(*) AS antall_linjer,SUM(t.belop_oere)/100.0 AS sum_belop_kr FROM transaksjon t JOIN leverandoer l ON l.id=t.leverandoer_id GROUP BY l.id,l.navn,CAST(t.periode/100 AS INTEGER);
CREATE VIEW v_skatt_per_aar AS SELECT aar,SUM(skatt_oere)/100.0 AS sum_skatt_kr,SUM(antall) AS antall FROM eiendomsskatt GROUP BY aar;
CREATE VIEW v_skatt_per_grunnkrets AS SELECT e.aar,g.nummer,g.navn,SUM(e.skatt_oere)/100.0 AS sum_skatt_kr,SUM(e.antall) AS antall FROM eiendomsskatt e JOIN grunnkrets g ON g.nummer=e.grunnkrets_nr GROUP BY e.aar,g.nummer,g.navn;
COMMIT;
